def _resolve_input(argv):
    """Find the input video: explicit argument first, then common names,
    then any lone MP4 beside the script or in the working directory."""
    args = list(argv[1:])
    for i, arg in enumerate(args):
        if arg in ("-i", "--input") and i + 1 < len(args):
            return args[i + 1]
        if arg.startswith("--input="):
            return arg.split("=", 1)[1]

    positional = [a for a in args if not a.startswith("-")]
    if positional:
        return positional[0]

    for candidate in ("/app/input.mp4", "/app/video.mp4", "/app/test.mp4",
                      "input.mp4", "video.mp4", "test.mp4"):
        if os.path.isfile(candidate):
            return candidate

    discovered = []
    seen = set()
    for directory in ("/app", os.getcwd()):
        try:
            names = sorted(os.listdir(directory))
        except OSError:
            continue
        for name in names:
            if not name.lower().endswith((".mp4", ".mov", ".avi", ".mkv")):
                continue
            path = os.path.abspath(os.path.join(directory, name))
            if path in seen:
                continue
            seen.add(path)
            if path == os.path.abspath("/app/example_video.mp4"):
                continue          # development video, only a fallback
            if os.path.isfile(path):
                discovered.append(path)
    if discovered:
        return discovered[0]

    if os.path.isfile("/app/example_video.mp4"):
        return "/app/example_video.mp4"
    raise SystemExit("usage: jump_analyzer.py <video.mp4>")
